const rossGuide={name:'Ross Bridge',white:[511,395,370,155,337,174,484,361,341,338,133,357,519,156,350,477,411,358],par:[5,4,4,3,4,3,5,4,4,4,3,4,5,3,4,5,4,4],advice:["Aim over the right fairway bunker to avoid water left. On the second shot, decide whether to lay up or challenge the water splitting the fairway for a birdie chance.","Avoid three fairway bunkers from the elevated tee on this dogleg left. The approach has another bunker; miss left rather than right or long toward the water.","Choose between challenging water and bunker with driver or laying back to the wider fairway. Avoid missing left of the long, narrow green, where high grass and water await.","The elevated tee shot plays entirely over water to a wide, undulating green with no bunker. Choose the right club for the 23-yard-deep surface.","A welcome break from water hazards. Favor the right side of the uphill fairway for the best angle into the wide, mostly flat elevated green.","This par 3 plays closer to 200 yards. Three bunkers guard the front of a large sloping green, and right-side pins are especially demanding.","A gentle dogleg right drops steeply downhill. A long drive can set up reaching in two, but avoid sand short and left of the massive, mostly flat green.","A long but downhill par 4 without bunkers. A hill right can return tee shots to play; water guards the left of the green. A front pin may invite a running approach.","Carry the cavernous central fairway bunker with a strong drive. The approach must find a green angled toward the lake and protected by two bunkers.","The sharp dogleg right calls for a left-to-right tee shot. Add a club to carry the massive bunker and reach the elevated green.","Take plenty of club to clear the false front. Short shots roll far down the hill, leaving a difficult chip to a heavily sloped green.","Favor a left-to-right tee shot for the approach angle. A deep front bunker guards the elevated green, but missing right leaves room.","This downhill par 5 plays shorter than its yardage. If laying up, carry the left fairway bunker about 150 yards out; avoid the severe downslope beyond the green.","Play conservatively to the center. A tucked pin tempts a miss into the bunker or water front-left.","From the elevated tee, choose how much to challenge. Leave a comfortable approach to the deep green, guarded by a front bunker and sloping toward water left.","Find the wide fairway for a chance to reach the shortest par 5 in two. Layups should finish short of the pinching bunkers for an approach to the large elevated green.","Two bunkers left encourage a tee shot right, but that leaves a difficult approach to one of the smallest greens, especially for a right pin.","Avoid three central fairway bunkers and the lake running along the right. Carry sand and water on approach, but stay short of the waterfall behind the green."]};
guideCourses.ross=[rossGuide];
const linksGuide={name:'Grand National Links',white:[366,470,151,360,375,499,409,299,146,309,160,493,352,372,467,144,368,385],par:[4,5,3,4,4,5,4,4,3,4,3,5,4,4,5,3,4,4],advice:["Find the fairway on this demanding opener. The approach plays significantly uphill, so take extra club; shots landing short of the green's center can roll back toward the front.","A multi-level fairway makes the tee shot interesting. Avoid fairway bunkers and the lake right on your second shot; two-putting the green is a challenge.","The heart-shaped green offers little forgiveness. Land in its middle half to avoid running over the back. Par is a strong result.","Don't attempt to carry the corner of Lake Saugahatchee. Aim near the 150-yard marker, then avoid bunkers in front of and beyond the subtle, tricky green.","Long hitters may carry the right fairway bunkers. The elevated green sits well above the landing area; take at least one extra club for the blind approach.","This is a three-shot par 5, and accuracy matters more than driver. Avoid the fairway bunker, lay up to 100–150 yards, and keep the approach clear of the marsh short and right.","One of the toughest holes on the Links. The large, multi-tiered green has major elevation changes; try to finish on the same tier as the hole.","Distance off the tee is unnecessary. Find the pedestal green with your approach: Lake Saugahatchee catches misses short or left, while long or right leaves a tough recovery.","Short is the only safe miss around this peninsula green. The putting surface is more than 50 yards deep, so club selection depends heavily on the pin.","A short par 4 that demands a precise approach to an elevated green sloping from front-right to back-left. Read its subtle undulations carefully.","An all-carry par 3 over wetlands to a pedestal green, with little margin for error. Take enough club to reach the putting surface.","The fairway narrows toward the green, making a two-shot attempt risky. Two prominent green ridges can redirect shots forward or toward the back-right.","The split fairway offers a choice: aggressive players can go left, while the safer route is right. Carry the wetland on approach to a rolling, difficult green.","Use the elevated right side of the fairway to feed shots toward the center; missing left leaves no approach. Avoid two front pot bunkers before the relatively flat green.","A risk-reward par 5 where long hitters may carry the left fairway bunker. Take extra club into the elevated green, guarded by two deep front bunkers.","Don't underestimate this short par 3. Avoid the deep pot bunker in front and pay attention to the green's subtle breaks.","The downhill tee shot adds distance; stay left of the fairway bunker. Hit your approach to or beyond the flag because short shots won't hold the intended target.","Carry the marsh and avoid the large fairway bunker off the tee. The approach must carry water to a pedestal green; the wrong section can leave an exceptionally long putt."]};
guideCourses.links=[linksGuide];
const lakeGuide={name:'Grand National Lake',white:[319,361,155,480,345,365,489,159,351,365,356,459,361,474,174,297,143,365],par:[4,4,3,5,4,4,5,3,4,4,4,5,4,5,3,4,3,4],advice:["Play the tee shot short or right of the fairway bunker. Choose the approach club carefully to avoid hazards short-right and left, and find the correct section of the large green.","Check the wind: water runs left and behind the green. Avoid fairway bunkers right and the lake left, then use a delicate approach to the semi-peninsula green.","Lake Saugahatchee catches shots short or left; a pot bunker and swale threaten the right. Club selection is crucial on this scenic par 3.","This par 5 offers a scoring opportunity. Take extra club for uphill approaches from inside 225 yards, then handle the undulating green with care.","Enjoy the elevated view, but stay focused. Three cross bunkers create tee-shot choices; precise club selection is needed for the multi-tiered green.","Stay left of the fairway bunker and short of the hidden lake straight ahead. The very deep double green is shared with hole 1.","Shot placement matters more than distance. Bunkers and the lake collect misses, while three green plateaus make putting demanding.","A demanding par 3 with a hard-to-hit green. The front of the putting surface sits considerably below the rest.","The uphill approach to an elevated green is blind from the fairway. Avoid the left fairway bunkers and keep the approach short of the flagstick.","One of the toughest holes. Find the fairway, then take extra club to the elevated green; the fronting fairway bunker creates a misleading sense of distance.","Conservative play is rewarded. The multi-level fairway adds roll, but the second shot plays slightly uphill into the prevailing wind; the green slopes back to front.","Lake Saugahatchee frames the entire left side of this picturesque par 5. Aim each shot slightly farther right than instinct suggests.","This difficult par 4 plays uphill into the prevailing wind. Avoid the fairway bunker and steep drop-off right, and take extra club on approach.","A bold tee shot can be rewarded or punished on this par 5. The small green is difficult to hit but offers a chance for a one-putt.","The signature island-green par 3 demands commitment amid swirling winds. Check the yardage, choose a club, and trust the swing.","A fun short par 4 where placement matters more than length. Avoid the marshy inlet in front of the green on approach.","The green has pronounced movement and feeds balls left. Try to land right of the flagstick.","Find the fairway on the closer. A collection area left of the green is a safe miss, but several ridges complicate the final putts."]};
guideCourses.lake=[lakeGuide];
const gnShortGuide={name:'Grand National Short Course',white:[130,148,128,115,124,112,119,133,113,108,139,119,98,104,143,156,110,119],par:Array(18).fill(3),advice:["Trees frame the opening hole. A bunker guards the front-left of the green, so favor the center and avoid coming up short on that side.","Trees and a front-left bunker make accuracy important. Do not go long: the ground falls sharply downhill toward water behind the green.","Trees line the left side, and a miss left is especially costly. With no bunker to contend with, favor a safe target away from the left.","A forgiving par 3 with a bunker short-left. Take a comfortable club and aim toward the open portion of the green.","Another forgiving hole, but a bunker guards the front-right. Favor the center or left portion of the green to avoid the sand.","A manageable, forgiving hole with a bunker short-left. Commit to enough club to clear the bunker.","No sand on this hole, but trouble waits to the right. Favor the center-left of the green and avoid pushing the tee shot.","The first water carry on the Short Course demands enough club to get all the way across. A small bunker guards the front-center; left is the bailout.","The shot crosses a small river. A bunker protects the front-right, while long-right is the preferred miss if you need extra room.","A short par 3 without water. Avoid the bunker short-right and concentrate on a controlled tee shot.","One of the longer holes, but there are no bunkers. Prioritize solid contact and a safe landing area.","Get the yardage right: a bunker guards the front of the green, but going long is also costly. Distance control is the key.","Two small bunkers protect the short and left sides, while water runs along the right. Choose a target that avoids both hazards.","Marsh and lake make the right side a no-go area. With no bunkers, the safer miss is left.","This tee shot is an all-carry over water. Short and right are in the water, so take enough club and favor the left as your bailout. No bunkers.","The longest White-tee hole has a large bunker directly in front and water or marsh along the right. Favor left, with enough club to clear the sand.","A welcome break from the water carries, though trouble remains to the right. A bunker sits behind the back-left of the green.","On the final hole, left is the safer miss. There is no water, but a bunker guards the front-right of the green."]};
guideCourses.short=[gnShortGuide];
function toGuide(x){return {name:x[0],code:x[1],white:x[2],par:x[3],advice:x[4]};}
function guideHoles(){return (guideCourses[roundId]||[]).flatMap(c=>c.white.map((white,i)=>({course:c.name,code:c.code,base:c.base||'https://www.rtjgolf.com/silverlakes/tour-2013/',hole:i+1,white,par:c.par[i],title:c.titles?.[i],advice:c.advice[i]})));}
const localGuidePaths={'Backbreaker':'silver-lakes/backbreaker','Mindbreaker':'silver-lakes/mindbreaker','Heartbreaker':'silver-lakes/heartbreaker','Short Course':'silver-lakes/short-course','Valley':'valley','Ridge':'ridge','The Back Yard':'backyard'};
function updateGuide(){
 const el=document.querySelector('#guide-content');if(!el)return;
 const item=guideHoles()[guideHole-1];if(!item)return;
 const sel=document.querySelector('#guide-hole');if(sel)sel.value=String(guideHole);
 const local=localGuidePaths[item.course]&&!(item.course==='The Back Yard'&&item.hole>6)?'/images/'+localGuidePaths[item.course]+'/hole-'+item.hole+'.webp':'';
 const image=local?'<img loading="lazy" src="'+local+'" alt="'+item.course+' hole '+item.hole+' map">':'<p class="guide-image-pending">Updated hole map pending</p>';
 el.innerHTML='<h3>'+item.course+' · Hole '+item.hole+'</h3><p class="hole-guide-hdcp">'+(item.title||'HDCP #'+rank(guideHole))+'</p><p class="hole-guide-par">Par '+item.par+' · <strong>'+(item.title?'Back':'White')+': '+item.white+' yards</strong></p><div class="hole-guide-navigation"><button type="button" class="hole-guide-arrow" data-guide-step="-1" aria-label="Previous hole" '+(guideHole===1?'disabled':'')+'>❮</button>'+image+'<button type="button" class="hole-guide-arrow" data-guide-step="1" aria-label="Next hole" '+(guideHole===guideHoles().length?'disabled':'')+'>❯</button></div><p>'+item.advice+'</p>';
 const img=el.querySelector('img');if(img)img.addEventListener('error',()=>{img.replaceWith(Object.assign(document.createElement('p'),{textContent:'Updated hole map pending'}));},{once:true});
}

let playingGroupOverrides={},groupDraft=null;
const defaultSkillsHoles=JSON.parse(JSON.stringify(skillsHoles));
let skillsHoleOverrides={};
let connectionState='connecting',lastSync=null,matchNotices=[],previousMatchStates=new Map(),hasMatchBaseline=false;
let me=null,roundId=rounds.some(x=>x.id===sessionStorage.getItem('rtj-round'))?sessionStorage.getItem('rtj-round'):'silver-am',tab=['scores','matches','boards','skills','settings'].includes(sessionStorage.getItem('rtj-tab'))?sessionStorage.getItem('rtj-tab'):'scores',scores=[],skills=[],skillsLocks=[],holes=[],submissions=[],ready=false,testMode=false,notice='',target=null,channel=null,timer=null;
const $=s=>document.querySelector(s),r=()=>rounds.find(x=>x.id===roundId);
const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');
const playingGroups=(id=roundId)=>playingGroupOverrides[id]||rounds.find(x=>x.id===id)?.groups||[];
const group=()=>playingGroups().find(g=>g.includes(me))||[];
const hole=(h)=>holes.find(x=>x.round_id===roundId&&x.hole===h);
const par=h=>hole(h)?.par??(r().id==='backyard'||r().id==='short'||(r().id==='silver-pm'&&h>9)?3:4);
const rank=h=>hole(h)?.stroke_index??h;
const strokes=(player,h)=>strokesOnHole(roundId,player,h,rank(h));
const score=(p,h)=>scores.find(s=>s.round_id===roundId&&s.player===p&&s.hole===h);
const net=(p,h)=>netScore(roundId,p,h,score(p,h),rank(h));
const through=(p,id=roundId)=>{const total=rounds.find(x=>x.id===id)?.holes||18;let h=0;while(h<total&&scores.some(x=>x.round_id===id&&x.player===p&&x.hole===h+1&&x.gross!=null))h++;return h;};
const syncStatus=()=>'<div class="sync-bar"><span class="sync-state '+(connectionState==='connected'?'sync-ok':'sync-warn')+'">'+(connectionState==='connected'?'● Live connected':connectionState==='offline'?'● Offline':'● Connecting…')+'</span><span class="small">'+(lastSync?'Synced '+new Date(lastSync).toLocaleTimeString():'Not synced yet')+'</span><button id="manual-refresh" type="button">↻ Refresh</button></div>';
function matchAlertPanel(){if(r().format!=='match')return '';const alerts=[];for(const g of r().groups){for(let i=0;i<g.length;i++)for(let j=i+1;j<g.length;j++){const a=g[i],b=g[j];if(a==='Mason'||b==='Mason')continue;let aw=0,bw,played=0;bw=0;for(let h=1;h<=r().holes;h++){const x=net(a,h),y=net(b,h);if(x===null||y===null)continue;played++;if(x<y)aw++;else if(y<x)bw++;}if(!played)continue;const lead=aw-bw;const key=roundId+'|'+a+'|'+b;const prev=previousMatchStates.get(key);const current={lead,played};if(hasMatchBaseline&&prev&&played>prev.played){if(lead===0&&prev.lead!==0)alerts.push(a+' vs '+b+': all square through '+played);else if(lead!==0&&(prev.lead===0||Math.sign(lead)!==Math.sign(prev.lead)))alerts.push((lead>0?a:b)+' takes the lead over '+(lead>0?b:a)+' through '+played);if(played===r().holes&&prev.played<r().holes)alerts.push(a+' vs '+b+': match complete');}previousMatchStates.set(key,current);}}if(alerts.length)matchNotices=[...alerts.map(x=>({round:roundId,message:x,time:Date.now()})),...matchNotices].slice(0,20);hasMatchBaseline=true;const relevant=matchNotices.filter(x=>x.round===roundId).slice(0,6);return '<section class="panel"><h3>Match Alerts</h3>'+(relevant.length?relevant.map(x=>'<p class="small">⚡ '+esc(x.message)+'</p>').join(''):'<p class="small">Lead changes, all-square moments and completed matches will appear here as scores update while this app is open.</p>')+'</section>';}
const throughLabel=(h,total)=>h===0?'—':h>=total?'F':'Thru '+h;
const sf=(p)=>{let n=0;for(let h=1;h<=r().holes;h++){let x=net(p,h);if(x===null)continue;let d=x-par(h);n+=d<=-1?3:d===0?2:d===1?1:0;}return n;};
function alignLiveMatchWindows(){
 document.querySelectorAll('#app .match-card-visual').forEach(card=>{
  const strip=card.querySelector('.match-progress-scroll');
  if(!strip)return;
  const latest=Number(strip.dataset.latestHole)||0;
  if(!latest)return;
  const cell=card.querySelector('.match-progress-hole');
  if(!cell)return;
  const width=cell.parentElement.getBoundingClientRect().width/Math.max(1,cell.parentElement.children.length);
  const visible=Math.max(1,Math.floor(strip.clientWidth/width));
  // Show approximately three previous holes, the latest hole and upcoming holes.
  const first=Math.max(1,Math.min(latest-3,latest-visible+1));
  const offset=Math.min(strip.scrollWidth-strip.clientWidth,Math.max(0,(first-1)*width));
  strip.scrollLeft=offset;
  const table=card.querySelector('.match-table-wrap');
  if(table)table.scrollLeft=offset;
 });
}
function pairingsPanel(round){
 const competitionTeams=teams[round.id]||[];
 const groupCards=playingGroups(round.id).map((players,i)=>'<div class="pairings-group"><strong>Group '+String.fromCharCode(65+i)+'</strong><div>'+players.map(p=>'<span class="pairings-player">'+esc(p)+'</span>').join('')+'</div></div>').join('');
 const fixedGroups=round.groups.map(g=>g.filter(p=>p!=='Mason'));
 const matchups=round.format==='match'?fixedGroups.flatMap(g=>g.flatMap((p,i)=>g.slice(i+1).map(opponent=>p+' vs '+opponent))):[];
 const teamName=round.format==='vegas'?'Vegas Teams':round.format==='triple'?'Triple Threat Sides':round.format==='skins'?'Gross Team Skins':round.format==='bestball'?'Best-Ball Teams':'Teams';
 const teamCards=competitionTeams.length?'<div class="pairings-teams"><h4>'+teamName+'</h4>'+competitionTeams.map((players,i)=>'<div class="pairings-team"><span class="pairings-team-label">Team '+(i+1)+'</span> '+players.map(esc).join(' + ')+'</div>').join('')+'<p class="small">These teams compete against the other listed teams, even when partners are in different tee groups.</p></div>':'';
 const matchupCards=matchups.length?'<div class="pairings-teams"><h4>Head-to-Head Matchups</h4>'+matchups.map(m=>'<div class="pairings-team">'+esc(m)+'</div>').join('')+'</div>':'';
 const individualNote=round.format==='stableford'?'Individual Stableford: golfers compete against the field; Mason also competes in Wild Card.':round.format==='finale'?'Individual net hole credits: all six golfers compete against one another.':round.format==='triple'?'Triple Threat Sides compete against each other; Wild Card Stableford is a separate individual contest.':round.format==='skins'?'Gross Team Skins: teams compete against one another; Wild Card individual skins is separate.':round.format==='vegas'?'Vegas Teams compete against one another on both nine-hole segments.':round.format==='bestball'?'Best-Ball Teams compete against the other listed teams.':'Head-to-head net matches are fixed independently of tee-group changes.';
 return '<details class="pairings-panel"><summary><span>Pairings &amp; Matchups</span><span class="pairings-chevron">⌄</span></summary><div class="pairings-content"><h4>Tee Groups</h4><div class="pairings-groups">'+groupCards+'</div>'+teamCards+matchupCards+'<p class="pairings-note">'+esc(individualNote)+'</p></div></details>';
}
function championshipSnapshot(){
 const engine=championship(scores,skills,holes,submissions,!testMode||isSpectator());
 const featured=[['trail','Trail Championship'],['cup','RTJ Cup'],...(wildCardSkillsRounds.includes(roundId)?[['wild','Wild Card Challenge']]:[])];
 return '<div class="championship-snapshot"><div class="championship-snapshot-heading"><strong>Championship Leaders</strong><span class="small">'+(testMode&&!isSpectator()?'Test standings':'Verified results only')+'</span></div><div class="championship-snapshot-grid '+(featured.length===3?'championship-snapshot-three':'championship-snapshot-two')+'">'+featured.map(([id,title])=>{
  const board=engine.boards.find(b=>b.id===id);
  if(!board||!board.rounds)return '<div class="championship-snapshot-card"><span>'+title+'</span><strong>Awaiting results</strong><small>0 / '+(board?.expected||0)+' events completed</small></div>';
  const sorted=[...board.eligible].sort((a,b)=>engine.compare(board,a,b));
  const leader=sorted[0],tied=sorted.filter(p=>engine.compare(board,p,leader)===0);
  const latest=engine.eventLabels[id]?.[engine.details[id].length-1]||'';
  return '<div class="championship-snapshot-card"><span>'+title+'</span><strong>'+tied.map(esc).join(' &amp; ')+'</strong><b>'+Number(board.values[leader].toFixed(3))+' pts</b><small>'+board.rounds+' / '+board.expected+' events · Last: '+esc(latest)+'</small></div>';
 }).join('')+'</div></div>';
}
