 locked=(!testMode||isSpectator())&&submissions.some(x=>x.round_id===roundId&&x.player===target);completed=scores.filter(x=>x.round_id===roundId&&x.player===target).length;const scorecardStatus=locked?'Final':completed>=r().holes?'Thru '+r().holes:'Thru '+through(target);body+='<p class="scorecard-progress"><strong>'+esc(target)+'</strong> · '+scorecardStatus+'</p>';
