$('#app').addEventListener('change',async e=>{let t=e.target;if(t.id==='guide-hole'){guideHole=Number(t.value)||1;updateGuide();return;}if(isSpectator()&&!(t.id==='round'||t.id==='target'||t.id==='guide-hole'))return;if(t.dataset.skillHole){if(me!=='Jimmy')return;const kind=t.dataset.skillHole,n=Number(t.value),defaults=defaultSkillsHoles[roundId]||{};if(!Object.hasOwn(defaults,kind)||!Number.isInteger(n)||n<1||n>r().holes){alert('Invalid contest hole.');await refresh();return;}const current=skillsHoles[roundId]||{};if(n===current[kind])return;const existing=skills.find(x=>x.round_id===roundId&&x.kind===kind&&x.winner);const warning=existing?' A winner is already recorded for this contest; it will NOT be cleared.':'';if(!confirm('Move '+(kind==='ctp'?'Closest to Pin':'Long Drive')+' from hole '+current[kind]+' to hole '+n+'? This updates the contest designation for everyone.'+warning)){render();return;}const updated={...current,[kind]:n};const x=await db.rpc('set_skills_holes',{p_round:roundId,p_holes:updated});if(x.error)alert(x.error.message);await refresh();return;}if(t.id==='test-mode'){let a=await db.rpc('set_test_mode',{p_enabled:t.checked});if(a.error)alert(a.error.message);await refresh();}else if(t.id==='round'){if(!rounds.some(x=>x.id===t.value))return;groupDraft=null;roundId=t.value;sessionStorage.setItem('rtj-round',roundId);target=null;render();}else if(t.id==='target'){target=t.value;render();}else if(t.dataset.movePlayer){if(me!=='Jimmy')return;const player=t.dataset.movePlayer,dest=Number(t.value);const groups=(groupDraft?.round===roundId?groupDraft.groups:playingGroups()).map(g=>[...g]);if(!Number.isInteger(dest)||dest<0||dest>=groups.length)return;for(const g of groups){const i=g.indexOf(player);if(i>=0)g.splice(i,1);}groups[dest].push(player);groupDraft={round:roundId,groups};render();}else if(t.dataset.lifeline){
 const h=Number(t.dataset.lifeline);
 if(target!=='Richie'||!lifelineEligible(roundId,h,rank(h))||!score('Richie',h)){alert('Lifeline is not eligible on this hole.');await refresh();return;}
 const a=await db.rpc('set_richie_lifeline',{p_round:roundId,p_hole:h,p_enabled:t.checked,p_test:testMode});
 if(a.error)alert(a.error.message);
 await refresh();
 }else if(t.dataset.skill){
 const kind=t.dataset.skill,eligible=[...(wildCardSkillsRounds.includes(roundId)?names:names.slice(0,6)),'NO_WINNER'];
 if(me!=='Jimmy'||skillsLocks.some(x=>x.round_id===roundId)||!Object.hasOwn(skillsHoles[roundId]||{},kind)||(t.value&&!eligible.includes(t.value))){notice='Not authorized or invalid contest';render();return;}
 const a=await db.rpc('set_skill_winner',{p_round:roundId,p_kind:kind,p_winner:t.value});
 if(a.error){alert('Unable to save skills result: '+a.error.message);notice=a.error.message;}
 await refresh();
 }else if(t.dataset.par||t.dataset.rank){let h=+(t.dataset.par||t.dataset.rank),v=+t.value;let old=hole(h);let a=await db.from('course_pars').upsert({round_id:roundId,hole:h,par:t.dataset.par?v:(old?.par??par(h)),stroke_index:t.dataset.rank?v:(old?.stroke_index??rank(h))});if(a.error)notice=a.error.message;await refresh();}else if(t.id==='ready'){let a=await db.rpc('set_scoring_ready',{p_ready:t.checked});if(a.error)notice=a.error.message;await refresh();}});
document.querySelector('#app').addEventListener('submit',async e=>{if(e.target.id!=='jimmy-pin-form')return;e.preventDefault();const pin=document.querySelector('#jimmy-pin')?.value||'';if(pin!=='2026'){notice='Incorrect organizer PIN.';render();return;}pendingJimmyPin=false;await login('Jimmy');});
// Keep the hole-result strip horizontally synchronized with the expanded scorecard.
document.querySelector('#app').addEventListener('scroll',e=>{
 const source=e.target;
 if(!source.matches?.('.match-progress-scroll, .match-card-visual .match-table-wrap'))return;
 const card=source.closest('.match-card-visual');
 if(!card)return;
 const peer=card.querySelector(source.matches('.match-progress-scroll')?'.match-table-wrap':'.match-progress-scroll');
 if(peer&&Math.abs(peer.scrollLeft-source.scrollLeft)>1)peer.scrollLeft=source.scrollLeft;
},true);
(async()=>{render();if(!db)return;let p=sessionStorage.getItem('rtj-player');if(p)await login(p);})();
